import {KButton,KDialog,KEmpty,KFacts,KNotice,KTabs,KTag,ScanPage} from './components';
import {CourseForm,GapForm,QuizForm,RevisionForm,SourceForm,UploadForm,VerdictForm,type RunAction} from './forms';
import {bookAllowed,citation,criticalDoubts,modeNames,profileNames,publicationGates,scopeNames,sourceAllowed,stageDescriptions,stageNames,storyReady,type KnowledgeBook,type KnowledgeCourse,type KnowledgeData,type KnowledgeStory} from './domain';
import './knowledge.css';
import {KnowledgeRuntimePanel,KnowledgePageEvidence,KnowledgeSourceExecution} from './KnowledgeRuntimePanel';
