type Overlay={type:'source'|'upload'|'book'|'publish'|'reviewAll'|'revision'|'history'|'story'|'quiz'|'quizResult'|'course'|'courseRemove'|'gap'|'sourceFailure'|'material'|'node'|'pageText'|'pageReview'|'newDoubt'|'storyDraft'|'storyReview'|'rescan';id?:string;version?:string;target?:string};
const routeTitles:Record<string,[string,string]>={sources:['知识接入','动态连接知识储备，授权与出处始终可查。'],temple:['知识神殿','独立故事相互连接，经典与解读各有来处。'],collation:['原文校对','保留原件，逐页精校，让每次裁决有迹可循。'],learning:['学习计划','按家人的兴趣与节奏，把知识讲成一条路线。'],originals:['原文基库','原件、校勘与知识衍生，分层保存。']};
function BookStatus({k,book}:{k:KnowledgeData;book:KnowledgeBook}){return book.status==='published'?<KTag tone={bookAllowed(k,book)?'good':'warn'}>原文 v{book.version} · {bookAllowed(k,book)?'已发布':'来源受限'}</KTag>:<KTag tone={book.stage>=5?'warn':'neutral'}>{book.stage>=5?`${book.doubts.filter(q=>q.status!=='resolved').length} 项待审疑点`:stageNames[book.stage]}</KTag>}
function StoryStatus({k,story,profile}:{k:KnowledgeData;story:KnowledgeStory;profile:string}){return <KTag tone={storyReady(k,story,profile)?'good':'warn'}>{story.dirty?'修订后待更新':storyReady(k,story,profile)?'可学习':'暂不可学习'}</KTag>}
function Metrics({items}:{items:{label:string;value:number|string;detail?:string}[]}){return <div className="kn-metrics">{items.map(item=><div key={item.label}><span>{item.label}</span><strong>{item.value}</strong>{item.detail&&<small>{item.detail}</small>}</div>)}</div>}
function Gates({k,book}:{k:KnowledgeData;book:KnowledgeBook}){return <div className="kn-gates">{publicationGates(k,book).map(g=><div className={g.ok?'pass':'blocked'} key={g.label}><span>{g.ok?'✓':'○'}</span>{g.label}</div>)}</div>}
function Pipeline({book}:{book:KnowledgeBook}){if(book.file){const entered=book.pageTexts?.length??0;return <div className="kn-pipeline">{[{label:'真实原件入库',done:book.file.stored},{label:(book.ocr?'机器候选 ':'人工转录 ')+entered+'/'+book.pages,done:entered===book.pages},{label:'逐页精校 '+book.reviewed.length+'/'+book.pages,done:book.reviewed.length===book.pages},{label:'正式发布',done:book.status==='published'}].map((s,i)=><div key={s.label} className={s.done?'done':'current'}><i>{s.done?'✓':i+1}</i><span>{s.label}</span></div>)}</div>;}return <div className="kn-pipeline">{stageNames.map((stage,index)=><div className={index<book.stage?'done':index===book.stage?'current':''} key={stage}><i>{index<book.stage?'✓':index+1}</i><span>{stage}</span></div>)}</div>}

export function KnowledgeGraph({k,profile,onStory,onBook}:{k:KnowledgeData;profile:string;onStory:(id:string)=>void;onBook:(id:string)=>void}){const stories=k.stories.filter(s=>profile==='me'&&k.books.some(b=>b.id===s.book&&(!['private','personal'].includes(b.scope||'')||!b.owner||b.owner===profile))||storyReady(k,s,profile)).slice(0,10);const referenced=k.books.filter(b=>stories.some(s=>s.book===b.id));const concepts=Array.from(new Set(stories.flatMap(s=>s.connections))).slice(0,8);const width=900,height=Math.max(400,Math.max(stories.length,concepts.length)*48+75);const conceptY=(i:number)=>(i+1)*height/(concepts.length+1);const storyY=(i:number)=>(i+1)*height/(stories.length+1);const bookY=(i:number)=>(i+1)*height/(referenced.length+1);return <div className="kn-graph-wrap"><svg viewBox={`0 0 ${width} ${height}`} className="kn-graph" role="group" aria-label="可交互知识关系图，概念连接故事，故事回到原文"><title>概念 → 独立故事 → 原文版本与页码</title><defs><linearGradient id="kn-graph-edge"><stop stopColor="var(--accent)" stopOpacity=".1"/><stop offset="1" stopColor="var(--accent)" stopOpacity=".4"/></linearGradient></defs><text x="95" y="22" className="kn-graph-heading">关联概念</text><text x="365" y="22" className="kn-graph-heading">独立故事</text><text x="700" y="22" className="kn-graph-heading">原文出处</text>{stories.flatMap((s,si)=>s.connections.map(concept=>{const ci=concepts.indexOf(concept);return ci<0?null:<path key={`${s.id}-${concept}`} d={`M165 ${conceptY(ci)} C260 ${conceptY(ci)},265 ${storyY(si)},345 ${storyY(si)}`} fill="none" stroke="url(#kn-graph-edge)"/>}))}{stories.map((s,i)=>{const bi=referenced.findIndex(b=>b.id===s.book);return bi<0?null:<path key={s.id} d={`M550 ${storyY(i)} C620 ${storyY(i)},620 ${bookY(bi)},710 ${bookY(bi)}`} fill="none" stroke="var(--accent)" strokeOpacity=".2"/>})}{concepts.map((c,i)=><g key={c}><circle cx="145" cy={conceptY(i)} r="5" fill="var(--accent)" opacity=".5"/><text x="130" y={conceptY(i)+4} textAnchor="end">{c}</text></g>)}{stories.map((s,i)=><g key={s.id} role="button" tabIndex={0} aria-label={`查看故事：${s.title}`} onClick={()=>onStory(s.id)} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onStory(s.id)}}} className={`kn-graph-node ${storyReady(k,s,profile)?'ready':'draft'}`}><rect x="345" y={storyY(i)-21} width="205" height="42" rx="7"/><text x="447" y={storyY(i)+4} textAnchor="middle">{s.title.length>14?s.title.slice(0,14)+'…':s.title}</text></g>)}{referenced.map((b,i)=><g key={b.id} role="button" tabIndex={0} aria-label={`查看原文：${b.title}`} onClick={()=>onBook(b.id)} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onBook(b.id)}}} className="kn-graph-node kn-graph-book"><rect x="710" y={bookY(i)-33} width="164" height="66" rx="8"/><text x="792" y={bookY(i)-3} textAnchor="middle">{b.title.length>12?b.title.slice(0,12)+'…':b.title}</text><text x="792" y={bookY(i)+16} textAnchor="middle" className="kn-graph-small">原文 v{b.version}</text></g>)}</svg><div className="kn-graph-legend"><span><i/>可学习故事</span><span><i className="draft"/>待发布或待更新</span><span>关系组织阅读路径，出处提供证据。</span></div>{!stories.length&&<KEmpty title="暂无对当前身份开放的知识关系"/>}</div>}

export function KnowledgePage({route,navigate}:{route:string;navigate:(route:string)=>void}){const {data,act}=useDemo();const live=data.runtime?.mode==='live';const k=data.knowledge as KnowledgeData;const profile=String(data.profile||'me');const manager=profile==='me';const personal=profile!=='public';const owned=(item:{scope?:string;owner?:string})=>!['private','personal'].includes(item.scope||'')||!item.owner||item.owner===profile;const managedBooks=k.books.filter(owned);const materials=k.materials.filter(owned);const favorites=personal?(k.favorites[profile]||[]):[];const profiles=(data.profiles||[]) as {id:string;name:string}[];const name=(id:string)=>profiles.find(p=>p.id===id)?.name||profileNames[id]||id;const [tab,setTab]=useState(route==='sources'?'registry':route==='collation'?'review':route==='learning'?'daily':route==='originals'?'books':'stories');const pendingTab=useRef('');const [bookId,setBookId]=useState('');const [doubtId,setDoubtId]=useState('');const [page,setPage]=useState(1);const [overlay,setOverlay]=useState<Overlay|null>(null);const [materialManager,setMaterialManager]=useState<{ids?:string[];materialId?:string}|null>(null);const [error,setError]=useState('');const [search,setSearch]=useState('');const [favoritesOnly,setFavoritesOnly]=useState(false);const [storyBookFilter,setStoryBookFilter]=useState('');const [graphTab,setGraphTab]=useState('graph');const speech=useSpeech(profile,data.preferences[profile]||{},{demo:!live});const speaking=speech.speaking;useEffect(()=>{setTab(pendingTab.current||(route==='sources'?'registry':route==='collation'?'review':route==='learning'?'daily':route==='originals'?'books':'stories'));pendingTab.current='';setSearch('');setError('')},[route]);useEffect(()=>{setOverlay(null);setError('');setFavoritesOnly(false);setStoryBookFilter('');speech.stop()},[profile]);useEffect(()=>()=>speech.stop(),[speech.stop]);const run:RunAction=async(action,payload)=>{try{await act(action,payload);setError('');return true}catch(err){setError(err instanceof Error?err.message:String(err));return false}};function go(next:string,nextTab?:string){setOverlay(null);if(route===next){if(nextTab)setTab(nextTab)}else{pendingTab.current=nextTab||'';navigate(next)}}function selectBook(id:string){setBookId(id);setDoubtId('');setPage(1)}function collate(id:string,nextTab='review'){selectBook(id);go('collation',nextTab)}const b=managedBooks.find(x=>x.id===bookId)||managedBooks.find(x=>x.status!=='published')||managedBooks[0];const q=b?.doubts.find(x=>x.id===doubtId)||b?.doubts.find(x=>x.status!=='resolved')||b?.doubts[0];const activeSources=k.sources.filter(s=>sourceAllowed(s,profile));const visibleSources=manager?k.sources.filter(owned):activeSources;const stories=k.stories.filter(s=>(manager&&managedBooks.some(book=>book.id===s.book)||storyReady(k,s,profile))&&(!storyBookFilter||s.book===storyBookFilter)&&(!favoritesOnly||favorites.includes(s.id))&&`${s.title} ${s.topic} ${s.connections.join(' ')}`.includes(search));const courses=personal?(k.courses[profile]||[]):[];const progress=personal?(k.progress[profile]||{}):{};const readyStories=k.stories.filter(s=>storyReady(k,s,profile));const published=k.books.filter(x=>x.status==='published'&&bookAllowed(k,x,profile));const totalDoubts=managedBooks.reduce((n,x)=>n+criticalDoubts(x).length,0);const [title,subtitle]=routeTitles[route]||routeTitles.temple;function openBook(id:string){const item=k.books.find(x=>x.id===id);if(item&&owned(item)&&(manager||item.status==='published'&&bookAllowed(k,item,profile)))setOverlay({type:'book',id})}function onStory(id:string){const s=k.stories.find(x=>x.id===id);if(s&&(manager&&managedBooks.some(book=>book.id===s.book)||storyReady(k,s,profile)))setOverlay({type:'story',id})}function narrate(story:KnowledgeStory){if(!storyReady(k,story,profile))return;if(speaking){speech.stop();return}speech.speak([story.title,...story.sections].join('。'),{language:'中文'});}
  const deepState=useRef({k,managedBooks,courses});deepState.current={k,managedBooks,courses};
  useEffect(()=>{function target(){const hash=location.hash.slice(1);const view=hash.includes('view=')?new URLSearchParams(hash).get('view')||'':hash.split('?')[0];const [next,encoded]=view.split('/');if(next!==route||!encoded)return;let id:string;try{id=decodeURIComponent(encoded)}catch{return}const current=deepState.current;if(route==='collation'&&manager&&current.managedBooks.some(b=>b.id===id)){setOverlay(null);setBookId(id);setDoubtId('');setPage(1);setTab('review')}else if(route==='sources'&&manager&&current.k.sources.some(s=>s.id===id&&owned(s)))setOverlay({type:'source',id});else if(route==='learning'&&personal&&current.courses.some(c=>c.id===id)){setTab('courses');requestAnimationFrame(()=>document.querySelector('[data-course-id="'+CSS.escape(id)+'"]')?.scrollIntoView({block:'center'}))}else if(route==='temple'){if(manager&&current.k.materials.some(material=>material.id===id&&owned(material))){setTab('books');requestAnimationFrame(()=>document.querySelector('[data-material-id="'+CSS.escape(id)+'"]')?.scrollIntoView({block:'center'}));return}const story=current.k.stories.find(s=>s.id===id);if(story&&(manager&&current.managedBooks.some(b=>b.id===story.book)||storyReady(current.k,story,profile)))setOverlay({type:'story',id});else if(current.managedBooks.some(b=>b.id===id&&(manager||b.status==='published'&&bookAllowed(current.k,b,profile))))setOverlay({type:'book',id});else if(manager&&current.k.gaps.some(g=>g.id===id))setOverlay({type:'gap',id});else if(personal&&current.courses.some(c=>c.id===id))setTab('courses')}}target();window.addEventListener('hashchange',target);return()=>window.removeEventListener('hashchange',target)},[route,profile]);
  function storyCard(s:KnowledgeStory){const ready=storyReady(k,s,profile);return <article className="panel kn-story-card" key={s.id}><header><span className="eyebrow">STORY / {s.id.toUpperCase().slice(0,15)}</span><StoryStatus k={k} story={s} profile={profile}/></header><h3>{s.title}</h3><p>{s.summary}</p><div className="kn-tags"><KTag>{s.topic}</KTag><KTag>{s.duration} 分钟</KTag><KTag>{s.level}</KTag></div><p className="kn-citation">{citation(k,s)}</p><div className="kn-actions"><KButton primary={ready} onClick={()=>onStory(s.id)}>{ready?'开始讲解':s.dirty?'查看修订影响':'查看发布状态'}</KButton><KButton disabled={!ready||!personal} onClick={()=>run('knowledge.story.favorite',{id:s.id,profile})}>{favorites.includes(s.id)?'已收藏':'收藏'}</KButton>{manager&&s.dirty&&<KButton disabled={!bookAllowed(k,k.books.find(x=>x.id===s.book))} onClick={()=>live?setOverlay({type:'storyReview',id:s.id}):run('knowledge.story.update',{id:s.id})}>更新派生</KButton>}</div></article>}
  function bookCard(item:KnowledgeBook){return <article className="panel kn-book-card" key={item.id}><div className="kn-cover"><strong>{item.cover}</strong><span>{live?'原件入库':'样例书目'}</span></div><div className="kn-book-card-content"><div className="kn-row kn-between"><h3>{item.title}</h3><BookStatus k={k} book={item}/></div><p>{item.edition}</p><div className="kn-tags"><KTag>{item.pages} 页</KTag><KTag>{item.rounds} 轮校对</KTag><KTag>{item.reviewed.length} 页精校</KTag></div><p className="kn-citation">{k.sources.find(s=>s.id===item.source)?.name} · {item.rights}</p><div className="kn-actions"><KButton onClick={()=>openBook(item.id)}>书目与原件</KButton>{manager&&<KButton primary={item.status!=='published'} onClick={()=>collate(item.id,item.status==='published'?'versions':'review')}>{item.status==='published'?'版本与修订':'进入校对'}</KButton>}</div></div></article>}
  function courseCard(c:KnowledgeCourse){const finished=c.stories.filter(id=>{const s=k.stories.find(x=>x.id===id),p=progress[id];return !!s&&storyReady(k,s,profile)&&(p?.complete||p?.correct)&&p?.version===s.version&&c.versions[id]===s.version}).length;const outdated=c.stories.some(id=>{const s=k.stories.find(x=>x.id===id);return !s||!storyReady(k,s,profile)||c.versions[id]!==s.version});return <article className="panel kn-course" data-course-id={c.id} key={c.id}><header><div><span className="eyebrow">{name(profile)}的学习路线</span><h3>{c.title}</h3></div><KTag tone={outdated?'warn':'good'}>{outdated?'来源或版本需检查':`${finished} / ${c.stories.length} 已掌握`}</KTag></header><p>{c.goal}</p><div className="kn-progress"><i style={{width:`${c.stories.length?finished/c.stories.length*100:0}%`}}/></div><div className="kn-course-lines">{c.stories.map((id,i)=>{const s=k.stories.find(x=>x.id===id);const allowed=!!s&&bookAllowed(k,k.books.find(x=>x.id===s.book),profile);const ready=!!s&&storyReady(k,s,profile)&&c.versions[id]===s.version;const complete=ready&&(progress[id]?.complete||progress[id]?.correct)&&progress[id]?.version===s?.version;return <div key={id}><i className={complete?'complete':''}>{complete?'✓':i+1}</i><div><strong>{allowed?s?.title:'课次来源暂不可用'}</strong><small>{s&&c.versions[id]!==s.version?'原文已修订，先更新故事并刷新课程':!ready?'待发布或来源受限':`原文 v${c.versions[id]} · ${s?.duration} 分钟`}</small></div><KButton disabled={!ready} onClick={()=>onStory(id)}>学习</KButton></div>})}</div><footer><span>{({theme:'跨书主题',book:'经典顺读',people:'人物脉络'} as Record<string,string>)[c.structure]||c.structure} · {({short:'约5分钟/次',normal:'约10分钟/次',long:'约15分钟/次'} as Record<string,string>)[c.pace]||c.pace}</span><div className="kn-actions"><KButton onClick={()=>run('knowledge.course.refresh',{id:c.id,profile})}>刷新课程版本</KButton><KButton onClick={()=>setOverlay({type:'courseRemove',id:c.id})}>移除课程</KButton></div></footer></article>}
  function sourcesView(){return <><Metrics items={[{label:'有效授权源',value:activeSources.length},{label:'本地与混合',value:activeSources.filter(s=>s.mode!=='live').length},{label:'实时知识源',value:activeSources.filter(s=>s.mode==='live').length},{label:manager?'待同步或异常':'可用范围',value:manager?activeSources.filter(s=>s.health!=='可用').length:'家庭共享'}]}/><KTabs current={tab} onChange={setTab} items={[{id:'registry',label:'来源登记'},{id:'query',label:'联合检索'},...(manager?[{id:'health',label:'运行策略'}]:[])]}/>{tab==='registry'&&<div className="kn-source-list">{visibleSources.filter(s=>`${s.name} ${s.topics}`.includes(search)).map(s=><article className="panel kn-source-card" key={s.id}><div className="kn-source-symbol">{s.type.includes('API')?'↗':'▤'}</div><div className="kn-source-content"><header><h3>{s.name}</h3><KTag tone={!s.authorized?'warn':s.active&&s.health==='可用'?'good':'neutral'}>{!s.authorized?'授权已撤销':!s.active?'已停用':s.health}</KTag></header><p>{s.topics}</p><div className="kn-source-meta"><span>{s.type}</span><span>{modeNames[s.mode]}</span><span>{scopeNames[s.scope]}</span><span>{s.count} {live?'条已发布或已同步资料':'条样例资料'}</span><span>同步 {s.sync}</span></div><p className="kn-citation">{s.rights}</p>{live&&<KnowledgeSourceExecution sourceId={s.id}/>}</div>{manager&&<div className="kn-actions kn-source-actions"><KButton onClick={()=>setOverlay({type:'source',id:s.id})}>配置与授权</KButton><KButton disabled={!s.active||!s.authorized} onClick={()=>run('knowledge.source.sync',{id:s.id})}>{live?'同步资料':'模拟同步'}</KButton><KButton disabled={!s.authorized&&!s.active} onClick={()=>run('knowledge.source.toggle',{id:s.id})}>{s.active?'停用':'启用'}</KButton></div>}</article>)}{!visibleSources.length&&<KEmpty title="暂无可用来源" detail="登记来源、确认授权并配置连接器后参与检索。"/>}</div>}{tab==='query'&&<QuerySection k={k} profile={profile} run={run} onSource={id=>manager&&setOverlay({type:'source',id})}/>} {tab==='health'&&manager&&<div className="kn-columns"><section className="panel"><h3>连接器与同步策略</h3>{[{title:'动态扩展',detail:'独立登记连接器，按来源切换本地、实时或混合模式。'},{title:'授权先于召回',detail:'停用与撤权即时影响检索；家庭课程只使用共享正式内容。'},{title:'异常与快照分开',detail:'同步故障保留已授权快照，实时部分不能伪装成完整结果。'},{title:'容量与并发有界',detail:live?'目录或 HTTP 同步按管理员允许列表执行；单轮有实际超时、字节、页数和文档上限。':'连接器数量可扩展；模拟模式不发送实际请求。'}].map(x=><div className="kn-setting-row" key={x.title}><strong>{x.title}</strong><p>{x.detail}</p></div>)}<div className="kn-actions">{!live&&activeSources.filter(s=>s.mode!=='local').map(s=><KButton key={s.id} onClick={()=>setOverlay({type:'sourceFailure',id:s.id})}>模拟 {s.name} 中断</KButton>)}</div></section><section className="panel"><h3>最近知识事件</h3><EventList items={k.events.slice(0,12)}/></section></div>}</>}
  function booksView(){const books=managedBooks.filter(item=>(manager||item.status==='published'&&bookAllowed(k,item,profile))&&`${item.title} ${item.edition}`.includes(search));return <><div className="kn-book-grid">{books.map(bookCard)}</div>{!books.length&&<KEmpty title="暂无对当前身份开放的原文"/>}<div className="kn-asset-grid">{[{name:'原件库',tag:'不可变原件',text:'扫描文件、页图、页序与元数据独立保留。识别和修订不会覆盖原件。'},{name:'校勘基库',tag:'精校后发布',text:'候选、忠实转录、规范化文本与人工裁决分层，每段原文保留页图位置。'},{name:'知识神殿',tag:'版本绑定',text:'故事、关系与课程引用明确原文版本；勘误后，派生内容先失效再重核。'}].map(a=><article className="panel kn-asset" key={a.name}><span>◇</span><h3>{a.name}</h3><p>{a.text}</p><KTag>{a.tag}</KTag></article>)}</div>{manager&&materials.length>0&&<section className="panel"><div className="kn-section-head"><h3>统一收件 · 待整理资料</h3><KTag>{materials.filter(m=>m.status==='pending').length} 条待处理</KTag></div><p className="kn-hint">保留原始文字、终端与提交者；转为草稿或来源候选，不直接发布。</p><div className="kn-material-list">{materials.map(m=><article data-material-id={m.id} key={m.id}><div><strong>{m.title}</strong><p>{(m.text||m.note||'尚未提交原始资料').slice(0,240)}</p><small>{name(m.owner)} · {m.terminal} · {scopeNames[m.scope]} · {m.at||m.created}</small></div><KTag tone={m.status==='pending'?'warn':'good'}>{m.status==='pending'?'待处理':m.status==='source'?'已转来源候选':'已转原文草稿'}</KTag>{live&&<KButton onClick={()=>setMaterialManager({ids:m.attachments?.map(asset=>asset.id)||[],materialId:m.status==='pending'?m.id:undefined})}>原件管理{m.attachments?.length?' · '+m.attachments.length+' 份':''}</KButton>}{m.status==='pending'&&<div className="kn-actions"><KButton onClick={()=>setOverlay({type:live||m.metadata?.kind==='scan-description'?'upload':'material',id:m.id,target:'book'})}>{live?'补交真实原件':m.metadata?.kind==='scan-description'?'登记扫描原件':'转原文草稿'}</KButton><KButton onClick={()=>setOverlay({type:'material',id:m.id,target:'source'})}>转来源候选</KButton></div>}</article>)}</div></section>}</>}
  function graphView(){return <section className="panel"><div className="kn-section-head"><div><h3>故事独立，关联有据</h3><p className="kn-hint">点击故事或原文节点，沿版本与页码回查。</p></div><KTag>示例知识结构</KTag></div><KTabs current={graphTab} onChange={setGraphTab} items={[{id:'graph',label:'关联图谱'},{id:'timeline',label:'阅读时间线'},{id:'citations',label:'出处索引'}]}/>{graphTab==='graph'&&<KnowledgeGraph k={k} profile={profile} onStory={onStory} onBook={openBook}/>} {graphTab==='timeline'&&<><KNotice>这是一条按故事组织的阅读顺序，用于连接主题与背景；不是历史事件的真实年代轴。</KNotice><div className="kn-reading-timeline">{k.stories.filter(s=>manager&&managedBooks.some(book=>book.id===s.book)||storyReady(k,s,profile)).map((s,i)=><button key={s.id} onClick={()=>onStory(s.id)}><i>{String(i+1).padStart(2,'0')}</i><div><span>{s.topic} · {s.duration} 分钟</span><h4>{s.title}</h4><p>{s.summary}</p><small>{citation(k,s)}</small></div></button>)}</div></>} {graphTab==='citations'&&<div className="kn-index-list">{k.stories.filter(s=>manager&&managedBooks.some(book=>book.id===s.book)||storyReady(k,s,profile)).map(s=><button key={s.id} onClick={()=>openBook(s.book)}><strong>{s.title}</strong><span>{citation(k,s)}</span></button>)}</div>}</section>}
  function gapsView(){return <><KNotice>建议说明补什么、为什么补、影响哪条路线。分数仅用于排序，不代表知识完整度或事实概率。</KNotice><div className="kn-gap-list">{k.gaps.map(g=><article className="panel kn-gap-card" key={g.id}><div className="kn-gap-priority"><strong>{g.score}</strong><span>优先级</span></div><div className="kn-gap-content"><header><h3>{g.title}</h3><KTag tone={g.state==='accepted'?'good':g.state==='pending'?'warn':'neutral'}>{({pending:'待决策',accepted:'已接受',deferred:'已暂缓',ignored:'已忽略'} as Record<string,string>)[g.state]||g.state}</KTag></header><p>{g.reason}</p><KFacts items={[["需要补齐",g.need],["影响路线",g.impact],["建议动作",g.action]]}/>{g.state==='accepted'&&<KNotice>下一步：{({search:'先检索已有来源',collect:'收集待补资料',story:'整理先修故事'} as Record<string,string>)[g.next||'']||g.next}。{g.note}</KNotice>}<div className="kn-actions"><KButton primary onClick={()=>setOverlay({type:'gap',id:g.id})}>{g.state==='accepted'?'调整安排':'接受建议'}</KButton><KButton onClick={()=>run('knowledge.gap.state',{id:g.id,state:'deferred'})}>暂缓</KButton><KButton onClick={()=>run('knowledge.gap.state',{id:g.id,state:g.state==='ignored'?'pending':'ignored'})}>{g.state==='ignored'?'恢复待决策':'忽略'}</KButton></div></div></article>)}</div></>}
  function collationView(){if(!manager)return <KEmpty title="原文校对由管理者负责" detail="你可以在知识神殿学习已经正式发布的内容。"/>;if(!b)return <KEmpty title="尚未登记书目" detail={live?'先上传真实原件，再登记逐页原文。':'上传文件元数据或登记内置样卷，再推进模拟解析。'}/>;return <div className="kn-collation"><aside className="panel kn-book-rail"><header>书目队列 · {k.books.length}</header>{managedBooks.map(item=><button key={item.id} className={b.id===item.id?'selected':''} onClick={()=>selectBook(item.id)}><strong>{item.title}</strong><small>{item.edition}</small><BookStatus k={k} book={item}/></button>)}</aside><div className="kn-collation-main"><div className="kn-section-head"><div><h3>{b.title}</h3><p className="kn-hint">{b.pages} 页 · {b.layout} · 原文 v{b.version}</p></div><KButton onClick={()=>openBook(b.id)}>原件与书目</KButton></div>{live&&<KnowledgeRuntimePanel book={b} allowed={bookAllowed(k,b)}/>}<KTabs current={tab} onChange={setTab} items={[{id:'review',label:'疑点裁决'},{id:'pages',label:'逐页精校'},{id:'versions',label:'修订派生'},{id:'audit',label:'证据日志'}]}/>{tab==='review'&&<section className="panel"><Pipeline book={b}/>{live&&b.stage<5?<div className="kn-parse-card"><span>▤</span><h3>{b.filename}</h3><p>真实原件已入库。可启动多轮识别，或逐页人工转录；识别状态与疑点在上方显示。</p><KButton primary onClick={()=>setTab('pages')}>登记逐页原文</KButton></div>:b.stage<5?<div className="kn-parse-card"><span>▤</span><h3>{b.filename}</h3><p>{stageDescriptions[b.stage]}</p><KTag>{stageNames[b.stage]} · {b.bytes}</KTag><KButton primary onClick={()=>run('knowledge.book.advance',{id:b.id})}>推进模拟解析</KButton></div>:q?<><div className="kn-doubt-tabs">{b.doubts.map(item=><button className={`${q.id===item.id?'selected':''} ${item.status==='resolved'?'resolved':''}`} key={item.id} onClick={()=>setDoubtId(item.id)}>{item.status==='resolved'?'✓ ':''}第 {item.page} 页 · {item.type}</button>)}</div><div className="kn-review"><ScanPage book={b} page={q.page} doubt={q}/><div className="kn-review-form"><div className="kn-section-head"><h3>第 {q.page} 页 · {q.type}</h3><KTag tone={q.status==='resolved'?'good':'warn'}>{q.status==='resolved'?'已裁决':['escalated','rescan'].includes(q.status)?'待补扫':q.critical?'关键疑点':'待审核'}</KTag></div><p className="kn-reading">{q.reason}</p>{b.status==='published'||q.status==='resolved'?<><KNotice>{b.status==='published'?'正式校勘记录只读。后续勘误通过修订流程，保留当前证据。':'本疑点已经裁决，仍需完成本页独立精校。'}</KNotice><div className="kn-candidate"><small>已裁决原文 · {q.reviewedBy||'人工确认'}</small><p>{q.corrected||q.decision}</p></div><KButton onClick={()=>setOverlay({type:'revision',id:b.id})}>进入原文修订</KButton></>:<VerdictForm key={`${b.id}-${q.id}-${q.status}`} book={b} doubt={q} profile={profile} run={run} onSaved={()=>{const next=b.doubts.find(x=>x.id!==q.id&&x.status!=='resolved');if(next)setDoubtId(next.id)}}/>}{live&&['escalated','rescan'].includes(q.status)&&<KButton onClick={()=>setOverlay({type:'rescan',id:b.id,target:q.id})}>上传真实补扫</KButton>}</div></div></>:<div className="kn-review"><ScanPage book={b} page={page}/><div><h3>忠实原文</h3><p className="kn-reading kn-transcription">{b.text}</p><h4>{live?'规范化文本 · 与原文分层':'现代释义 · 与原文分层'}</h4><p className="kn-reading">{b.normalized}</p><KNotice>当前没有待裁决疑点。仍需完成逐页复核，才能发布精校版。</KNotice></div></div>}<div className="kn-quality"><Gates k={k} book={b}/><div className="kn-actions">{b.stage>=4&&b.status!=='published'&&<KButton onClick={()=>run('knowledge.book.recheck',{id:b.id})}>{live?'登记人工复查':'模拟复校一轮'} · {b.rounds} 轮</KButton>}<KButton primary onClick={()=>setOverlay({type:b.status==='published'?'revision':'publish',id:b.id})}>{b.status==='published'?'修订原文':'审核发布门槛'}</KButton></div></div></section>}{tab==='pages'&&<section className="panel"><div className="kn-section-head"><h3>逐页人工精校</h3><KTag tone={b.reviewed.length===b.pages?'good':'neutral'}>{b.reviewed.length} / {b.pages} 已复核</KTag></div><div className="kn-page-picker">{Array.from({length:b.pages},(_,i)=>i+1).map(p=><button key={p} aria-label={`第${p}页${b.reviewed.includes(p)?'，已复核':''}`} className={`${page===p?'selected':''} ${b.reviewed.includes(p)?'reviewed':''} ${b.doubts.some(d=>d.page===p&&d.status!=='resolved')?'doubt':''}`} onClick={()=>setPage(p)}>{b.reviewed.includes(p)?'✓ ':''}{p}</button>)}</div><div className="kn-review"><ScanPage book={b} page={page}/><div className="kn-page-transcript"><h3>第 {page} 页 · 忠实转录</h3>{live&&b.status!=='published'&&<div className="kn-actions"><KButton primary onClick={()=>setOverlay({type:'pageText',id:b.id})}>登记本页原文</KButton><KButton onClick={()=>setOverlay({type:'newDoubt',id:b.id})}>登记疑点</KButton></div>}<p className="kn-reading kn-transcription">{live?b.pageTexts?.find(p=>p.page===page)?.nonTextPage?(b.pageTexts.find(p=>p.page===page)?.nonTextKind==='illustration'?'人工分类：仅插图页，原文为空':'人工分类：空白页，原文为空'):b.pageTexts?.find(p=>p.page===page)?.text||'本页尚未登记原文':b.text}</p>{live&&<KnowledgePageEvidence book={b} page={page}/>}<KNotice>{live?'真实原件、机器候选与人工转录分别保存，必须逐页人工复核。':'样例页图、忠实转录与释义分别保存。批量确认只是流程演示，实际系统不能用它代替人工逐页审核。'}</KNotice><div className="kn-actions"><KButton primary disabled={b.stage<5||b.reviewed.includes(page)||b.doubts.some(d=>d.page===page&&d.status!=='resolved')} onClick={async()=>{if(live)setOverlay({type:'pageReview',id:b.id});else if(await run('knowledge.book.reviewPage',{id:b.id,page}))setPage(Math.min(page+1,b.pages))}}>{b.reviewed.includes(page)?'本页已复核':'确认本页精校'}</KButton><KButton disabled={live||b.status==='published'||b.stage<5||b.doubts.some(q=>q.status!=='resolved')} onClick={()=>setOverlay({type:'reviewAll',id:b.id})}>{live?'须逐页复核':'模拟完成全卷'}</KButton></div>{b.stage<5&&<p className="kn-hint">{live?'请先登记本页忠实原文。':'先完成 OCR 与交叉校对。'}</p>}{b.doubts.some(d=>d.page===page&&d.status!=='resolved')&&<p className="kn-hint kn-warning">本页疑点待裁决，暂不能确认。</p>}</div></div><div className="kn-quality"><Gates k={k} book={b}/><KButton primary onClick={()=>setOverlay({type:b.status==='published'?'revision':'publish',id:b.id})}>{b.status==='published'?'修订原文':'审核发布'}</KButton></div></section>}{tab==='versions'&&<><section className="panel"><div className="kn-section-head"><h3>原文版本与勘误传播</h3><KButton disabled={b.status!=='published'} onClick={()=>setOverlay({type:'revision',id:b.id})}>新增修订</KButton></div><div className="kn-version-row"><span>v{b.version}</span><div><strong>当前{b.status==='published'?'正式':'待发布'}原文</strong><p>{b.text}</p><small>{b.edition} · {b.published||b.created}</small></div><BookStatus k={k} book={b}/></div>{b.revisions.slice().reverse().map(r=><div className="kn-version-row" key={r.version}><span>v{r.version}</span><div><strong>{r.reason}</strong><p>{r.text}</p><small>{r.date||r.time} · 历史版本保留</small></div><KButton onClick={()=>setOverlay({type:'history',id:b.id,version:r.version})}>查看</KButton></div>)}<KNotice>原文修订后，故事先进入待更新；旧课程保留旧版引用，重核故事后再刷新课程。</KNotice></section><div className="kn-story-grid">{k.stories.filter(s=>s.book===b.id).map(storyCard)}</div></>}{tab==='audit'&&<section className="panel"><h3>识别、裁决与发布证据</h3><KFacts items={[["原件指纹",b.scanHash],["识别轮次",`${b.rounds} 轮`],["样本页数",`${b.pages} 页`],["原文版本",`v${b.version}`]]}/><KNotice>{live?'SHA256来自实际入库文件；展示时会再次校验原件指纹。':'原件指纹是模拟标识，不是对实际文件计算的 SHA256。'}</KNotice><EventList items={b.audit.slice().reverse()}/></section>}</div></div>}
  function learningView(){
    const storyProgress=Object.entries(progress).map(([id,p])=>({s:k.stories.find(x=>x.id===id),p})).filter(item=>item.s&&bookAllowed(k,k.books.find(b=>b.id===item.s?.book),profile));
    const learning=personal?(data.learning[profile]||{}):{};const activities=personal?(Array.isArray(learning.events)?learning.events:[]):[];const preference=personal?(data.preferences[profile]||{}):{};const corrections=activities.flatMap((event:any)=>(Array.isArray(event.corrections)?event.corrections:[]).map((correction:any)=>({event,correction})));const live=data.runtime?.mode==='live';
    return <><Metrics items={[{label:'本人学习分钟',value:personal?learning.minutes??0:'—'},{label:'完成练习',value:personal?learning.completed??0:'—'},{label:'活跃天数',value:personal?learning.days??0:'—'},{label:'我的课程',value:personal?courses.length:'—'}]}/><KTabs current={tab} onChange={setTab} items={[{id:'daily',label:'今日练习'},{id:'activities',label:'练习记录'},{id:'courses',label:'课程路线'},{id:'progress',label:'故事进度'},{id:'review',label:'纠错复习'},{id:'questions',label:'知识问答'}]}/>
    {tab==='daily'&&<><KNotice>{personal?name(profile)+'的语言、故事与课程记录在一个空间汇总。':'公共空间不读取任何人的学习数据；确认本人身份后保存练习。'}{live?' 实际练习可记录；AI纠错与评分须有真实评估结果。':''}</KNotice>{personal&&<section className="panel"><div className="kn-section-head"><h3>按我的节奏学习</h3><KButton onClick={()=>navigate('personas')}>调整偏好</KButton></div><KFacts items={[["语言",preference.language||'尚未设置'],["等级",preference.level||'尚未设置'],["节奏",preference.pace||'尚未设置'],["纠错偏好",preference.correction||preference.correctStyle||'尚未设置']]}/></section>}<div className="kn-story-grid"><article className="panel"><KTag>语言表达</KTag><h3>聊聊今天</h3><p className="kn-hint">逐轮回答、温和纠正，结束后保留练习记录。</p><KButton primary onClick={()=>navigate('chat/english')}>开始口语陪练</KButton></article><article className="panel"><KTag>历史与人物</KTag><h3>听一个有出处的故事</h3><p className="kn-hint">故事、原文与问答相连；按个人课程继续。</p><KButton primary onClick={()=>readyStories[0]?onStory(readyStories[0].id):go('temple','stories')}>开始故事学习</KButton></article><article className="panel"><KTag>科学与思考</KTag><h3>把知识说回来</h3><p className="kn-hint">从已发布故事的小问题开始，理解后再复习。</p><KButton primary disabled={!personal||!readyStories.length} onClick={()=>setOverlay({type:'quiz',id:readyStories.find(s=>/科学|地理|数学|自然/.test(s.topic))?.id||readyStories[0]?.id})}>理解问答</KButton></article></div><section className="panel"><div className="kn-section-head"><h3>最近练习</h3><KButton disabled={!personal} onClick={()=>setTab('activities')}>全部记录</KButton></div>{activities.slice(0,3).map((event:any)=><article className="kn-learning-summary" key={event.id||event.time}><h4>{event.title}</h4><p className="kn-hint">{event.time||event.day||'时间未记录'} · {event.minutes??'—'} 分钟{typeof event.score==='number'?' · '+event.score+' 分':''}</p></article>)}{!activities.length&&<KEmpty title={live?'暂无实际练习记录':personal?'还没有练习记录':'先确认本人身份'} detail={live?'实际答句与人工记录的分钟会保留，未评估时不显示成绩。':'完成一次口语或语音学习后，记录将在这里出现。'}/>}</section></>}
    {tab==='activities'&&<section className="panel"><h3>{name(profile)}的练习记录</h3><KNotice>只读取当前人的家庭陪练与语音学习记录。历史样例未保存逐轮答句或纠错时，明确保留缺项。</KNotice><div className="kn-progress-list">{activities.map((event:any)=>{const rounds=Array.isArray(event.rounds)?event.rounds:Array.isArray(event.answers)?event.answers:[];const fixes=Array.isArray(event.corrections)?event.corrections:[];return <article className="kn-practice-record" key={event.id||event.time}><div><strong>{event.title}</strong><small>{event.time||event.day||'时间未记录'} · {event.minutes??'—'} 分钟 · {rounds.length?rounds.length+' 轮答句':'轮次未记录'}{typeof event.score==='number'?' · '+event.score+' 分':''}</small><details><summary>答句与纠错 · {fixes.length} 项已保存纠错</summary>{rounds.map((answer:any,index:number)=><p key={index}><b>第 {index+1} 轮：</b>{typeof answer==='string'?answer:answer.answer||answer.text||answer.reply||'答句未记录'}{typeof answer==='object'&&answer.question&&<small>问题：{answer.question}</small>}{typeof answer==='object'&&answer.feedback&&<small>当时反馈：{answer.feedback}</small>}</p>)}{!rounds.length&&<p className="kn-hint">这次历史记录未保存逐轮答句，不补造轮次。</p>}{fixes.map((fix:any,index:number)=><p key={index}>{typeof fix==='string'?fix:<><b>{fix.original||fix.before||'原表达'}</b> → {fix.corrected||fix.after||fix.text||fix.feedback||'修正说明未记录'}{fix.reason&&<small>{fix.reason}</small>}</>}</p>)}{!fixes.length&&<p className="kn-hint">本次没有已保存纠错，不生成虚构评价。</p>}</details></div><KButton onClick={()=>navigate(event.type==='language'?'chat/english':'chat/story')}>继续练习</KButton></article>})}</div>{!activities.length&&<KEmpty title={live?'暂无已接入练习记录':'还没有个人练习记录'} detail="课程问答另在故事进度页保留；完成语言或语音练习后可回到这里复习。"/>}</section>}
    {tab==='courses'&&<><KNotice>{name(profile)}的个人路线，课程、收藏和进度独立保存。原文变化时须刷新课程版本。</KNotice><div className="kn-course-grid">{courses.map(courseCard)}</div>{!courses.length&&<KEmpty title="还没有个人课程" detail="从已发布故事中，选择一个问题或一条经典路线。"/>}</>}
    {tab==='progress'&&<section className="panel"><h3>{name(profile)}的故事学习记录</h3><div className="kn-progress-list">{storyProgress.map(({s,p})=>s&&<article key={s.id}><div><strong>{s.title}</strong><small>{p.last||p.at||'暂无时间记录'} · {p.attempts||0} 次练习 · 学习版本 v{p.version||'未记录'}</small></div><KTag tone={p.version!==s.version?'warn':(p.complete||p.correct)?'good':'neutral'}>{p.version&&p.version!==s.version?'旧版学习记录':(p.complete||p.correct)?'已掌握':p.listened?'已听过 · 待问答':'待再练习'}</KTag><KButton disabled={!storyReady(k,s,profile)} onClick={()=>onStory(s.id)}>回顾故事</KButton></article>)}</div>{!storyProgress.length&&<KEmpty title="第一段学习，从一个故事开始" detail="听完与答题分开记录，掌握情况以练习结果为准。"/>}</section>}
    {tab==='review'&&<><section className="panel"><h3>已保存纠错复习</h3><div className="kn-progress-list">{corrections.map(({event,correction}:any,index:number)=><article key={index}><div><strong>{event.title}</strong><p>{typeof correction==='string'?correction:<>{correction.original||correction.before||'原表达'} → {correction.corrected||correction.after||correction.feedback||correction.text}</>}</p><small>{event.time||event.day}</small></div><KButton onClick={()=>navigate('chat/english')}>再说一次</KButton></article>)}</div>{!corrections.length&&<KEmpty title="暂无已保存纠错" detail="复习使用原练习记录，不为历史样例生成推测纠错。"/>}</section><section className="panel"><h3>故事复习安排</h3><p className="kn-hint">按练习结果建议回访，不会自动发送通知或建立真实日程。</p><div className="kn-progress-list">{storyProgress.map(({s,p})=>s&&<article key={s.id}><div><strong>{s.title}</strong><small>{p.version!==s.version?'版本已变化，先回查原文':p.correct?'明天用自己的话回忆一次':'今天再听一次，比较两种说法'}</small></div><KTag>{p.review||'待问答后安排'}</KTag><KButton primary disabled={!storyReady(k,s,profile)} onClick={()=>setOverlay({type:'quiz',id:s.id})}>复习问答</KButton></article>)}</div>{!storyProgress.length&&<KEmpty title="暂无故事复习安排" detail="先听一个故事并完成小问题，建议将随记录呈现。"/>}</section></>}
    {tab==='questions'&&<div className="kn-story-grid">{readyStories.map(s=><article className="panel kn-question-card" key={s.id}><KTag>{s.topic}</KTag><h3>{s.quiz.question}</h3><p>{s.title}</p><KButton primary disabled={!personal} onClick={()=>setOverlay({type:'quiz',id:s.id})}>开始问答</KButton></article>)}{!readyStories.length&&<KEmpty title="暂无可用问答" detail="正式发布且来源有效的故事才能进入学习。"/>}</div>}</>
  }
  function dialogs():ReactNode{if(!overlay)return null;const item=k.books.find(x=>x.id===overlay.id);const source=k.sources.find(x=>x.id===overlay.id);const story=k.stories.find(x=>x.id===overlay.id);const gap=k.gaps.find(x=>x.id===overlay.id);const material=k.materials.find(x=>x.id===overlay.id);const close=()=>{setOverlay(null);setError('');speech.stop()};const wrap=(heading:string,children:ReactNode,footer?:ReactNode,wide=false)=><KDialog title={heading} onClose={close} footer={footer} wide={wide}>{children}{(error||speech.speechError)&&<p className="form-error" role="alert">{error||speech.speechError}</p>}</KDialog>;if(live&&overlay.type==='revision'&&item&&manager)return wrap('修订忠实原文',<PageRevisionForm book={item} run={run} onSaved={close}/>);if(live&&overlay.type==='rescan'&&item&&manager&&overlay.target)return wrap('补交真实扫描证据',<RescanForm book={item} doubtId={overlay.target} run={run} onSaved={close}/>);if(live&&overlay.type==='pageText'&&item&&manager)return wrap('登记逐页忠实原文',<PageTextForm book={item} page={page} run={run} onSaved={close}/>);if(live&&overlay.type==='pageReview'&&item&&manager)return wrap('逐字人工精校',<PageReviewForm book={item} page={page} run={run} onSaved={()=>{close();setPage(Math.min(page+1,item.pages))}}/>);if(live&&overlay.type==='newDoubt'&&item&&manager)return wrap('登记本页疑点',<DoubtForm book={item} page={page} run={run} onSaved={close}/>);if(live&&overlay.type==='storyDraft'&&manager)return wrap('登记有出处的故事草稿',<StoryDraftForm k={k} run={run} onSaved={close}/>,undefined,true);if(live&&overlay.type==='storyReview'&&story&&manager){const original=k.books.find(b=>b.id===story.book);return original?wrap('人工复核故事',<StoryReviewForm story={story} book={original} run={run} onSaved={close}/>,undefined,true):null;}if(overlay.type==='source'&&manager)return wrap(source?'知识源配置与授权':'登记知识来源',<SourceForm key={source?.id||'new'} source={source} onSubmit={async payload=>{const ok=await run('knowledge.source.save',payload);if(ok)close();return ok}}/>);if(overlay.type==='upload'&&manager)return wrap('上传扫描原件',<UploadForm k={k} material={material} onSubmit={async payload=>{const ok=await run('knowledge.book.upload',payload);if(ok){setBookId('');setDoubtId('');setPage(1);go('collation','review')}return ok}}/>);if(overlay.type==='book'&&item&&owned(item)&&(manager||item.status==='published'&&bookAllowed(k,item,profile)))return wrap('书目、原件与三层资产',<><div className="kn-book-detail"><div className="kn-cover"><strong>{item.cover}</strong><span>{live?'原件入库':'样例书目'}</span></div><div><h3>{item.title}</h3><p>{item.edition}</p><BookStatus k={k} book={item}/><p className="kn-hint">{item.rights}</p></div></div><KFacts items={[["作者 / 编者",item.author],["来源",k.sources.find(s=>s.id===item.source)?.name],["原件文件",item.filename],["文件大小",item.bytes],["原件标识",item.scanHash],["原文版本",`v${item.version}`],["版式",item.layout],["创建时间",item.created]]}/>{live&&manager&&<KnowledgeRuntimePanel book={item} allowed={bookAllowed(k,item)}/>}<div className="kn-layer-grid"><div><h4>原件库</h4><p>{item.pages} 页原件元数据，独立保留，不被 OCR 覆盖。</p></div><div><h4>校勘基库</h4><p>{item.rounds} 轮校对，{item.reviewed.length}/{item.pages} 页精校，{item.doubts.filter(q=>q.status==='resolved').length}/{item.doubts.length} 疑点已裁决。</p></div><div><h4>知识神殿</h4><p>{k.stories.filter(s=>s.book===item.id).length} 个关联故事，{k.stories.filter(s=>s.book===item.id&&s.dirty).length} 个待更新。</p></div></div><h4>同作品版本 · 独立保存</h4><div className="kn-relative-editions">{managedBooks.filter(other=>other.cover===item.cover&&other.id!==item.id&&(manager||other.status==='published'&&bookAllowed(k,other,profile))).map(other=><button key={other.id} onClick={()=>setOverlay({type:'book',id:other.id})}>{other.title} · {other.edition} · v{other.version}</button>)}{!managedBooks.some(other=>other.cover===item.cover&&other.id!==item.id)&&<p className="kn-hint">尚未登记其他版本。新版本保留独立原件、页码和校勘记录。</p>}</div><KNotice>{live?'真实原件独立保存，每个版本需逐页校对与发布。原图不清楚时补交证据。':'示例元数据与页图不能证明真实扫描质量。每个版本都需独立校对与发布。'}</KNotice></>,<>{manager&&<KButton primary onClick={()=>collate(item.id)}>进入校对台</KButton>}<KButton onClick={()=>{go('temple','stories');setSearch('');setStoryBookFilter(item.id);}}>查看关联故事</KButton></>,true);if(overlay.type==='publish'&&item&&manager){const gates=publicationGates(k,item),blocked=gates.some(g=>!g.ok);return wrap('原文正式发布',<><KNotice warn={blocked}>{blocked?'门槛尚未满足，继续校对后再发布。':'已知疑点已裁决，逐页精校完成，可发布正式原文。'}</KNotice><Gates k={k} book={item}/><p className="kn-reading">正式版保留来源、版本、疑点裁决与复核记录。精校不证明绝对零错误；后续勘误创建修订并重核派生。</p></>,<><KButton onClick={()=>collate(item.id,'pages')}>继续逐页精校</KButton><KButton primary disabled={blocked} onClick={async()=>{if(await run('knowledge.book.publish',{id:item.id,expectedVersion:item.revision,confirmed:live?true:undefined}))close()}}>确认发布 v{item.version}</KButton></>)}if(overlay.type==='reviewAll'&&item&&manager&&!live)return wrap('模拟全卷人工精校',<><KNotice warn>此按钮演示逐页审核完成后的状态，仅适用于模拟模式。真实校对系统不能替代逐页人工检查。</KNotice><Gates k={k} book={item}/><p className="kn-reading">将为 {item.pages} 个样例页面记录复核结果；尚有未裁决疑点时不允许执行。</p></>,<KButton primary disabled={item.status==='published'||item.stage<5||item.doubts.some(q=>q.status!=='resolved')} onClick={async()=>{if(await run('knowledge.book.reviewAll',{id:item.id}))close()}}>确认模拟全卷精校</KButton>);if(overlay.type==='revision'&&item&&manager)return wrap('原文修订与派生影响',<RevisionForm book={item} run={run} onSaved={()=>{close();setTab('versions')}}/>);if(overlay.type==='history'&&item&&owned(item)&&(manager||item.status==='published'&&bookAllowed(k,item,profile))){const r=item.revisions.find(x=>x.version===overlay.version);return r?wrap(`原文历史版 · v${r.version}`,<><h3>{item.title}</h3><p className="kn-reading kn-transcription">{r.text}</p><KFacts items={[["修订依据",r.reason],["保存时间",r.date||r.time]]}/><KNotice>历史版用于溯源，新课程使用当前正式原文。原件与历史记录均保留。</KNotice></>):null}if(overlay.type==='story'&&story&&managedBooks.some(book=>book.id===story.book)){const ready=storyReady(k,story,profile);if(!ready&&!manager)return null;return wrap(ready?`独立故事 · ${story.duration} 分钟`:'故事发布与修订状态',ready?<><div className="kn-section-head"><div><KTag>{story.topic} · {story.level}</KTag><h3 className="kn-story-title">{story.title}</h3></div><KTag tone="good">{name(profile)}的学习</KTag></div><blockquote className="kn-quote"><small>引用或教学样例</small>{story.quote}</blockquote><div className="kn-story-sections">{story.sections.map((text,i)=><p key={i}><span>{String(i+1).padStart(2,'0')}</span>{text}</p>)}</div><KNotice>{live?'中央朗读按本人安静时间、预算与隐私策略执行。原文与教学解读分层呈现。':'演示朗读使用浏览器声音，原文与教学解读分层呈现。'}</KNotice><CentralVoicePermission speech={speech}/><p className="kn-citation">{citation(k,story)}</p><div className="kn-tags">{story.connections.map(x=><KTag key={x}>{x}</KTag>)}</div>{progress[story.id]?.listened&&<p className="kn-hint">已记录听过；掌握情况仍由问答确认。</p>}</>:<><h3>{story.title}</h3><KNotice warn>{story.dirty?`故事引用 v${story.version}，最新原文 v${k.books.find(x=>x.id===story.book)?.version}。先重核派生内容，再刷新课程。`:'故事尚未完成解读复核，或原文、授权与版本不可用，暂不能进入正式教学。'}</KNotice><p className="kn-reading">{story.summary}</p><p className="kn-citation">{citation(k,story)}</p></>,ready?<><KButton onClick={()=>narrate(story)}>{speaking?'停止朗读':live?'中央朗读':'演示朗读'}</KButton><KButton disabled={!personal} onClick={()=>run('knowledge.story.listen',{id:story.id,profile})}>{live?'记录听完':'记录模拟听完'}</KButton><KButton disabled={!personal} onClick={()=>run('knowledge.story.favorite',{id:story.id,profile})}>{favorites.includes(story.id)?'取消收藏':'收藏'}</KButton><KButton primary disabled={!personal} onClick={()=>{speech.stop();setOverlay({type:'quiz',id:story.id})}}>回答小问题</KButton></>:<>{story.dirty&&<KButton primary onClick={async()=>{if(live)setOverlay({type:'storyReview',id:story.id});else if(await run('knowledge.story.update',{id:story.id}))close()}}>更新派生内容</KButton>}{live&&<KButton primary disabled={k.books.find(b=>b.id===story.book)?.status!=='published'} onClick={()=>setOverlay({type:'storyReview',id:story.id})}>复核解读</KButton>}<KButton onClick={()=>collate(story.book)}>审核关联原文</KButton></>,true)}if(overlay.type==='quiz'&&personal&&story&&storyReady(k,story,profile))return wrap('把知识说回来',<QuizForm k={k} story={story} profile={profile} run={run} onSaved={()=>setOverlay({type:'quizResult',id:story.id})}/>);if(overlay.type==='quizResult'&&personal&&story&&storyReady(k,story,profile)){const p=progress[story.id];return wrap(p?.correct?'理解得很好':'再想一想这个角度',<><KNotice warn={!p?.correct}>{story.quiz.explanation}</KNotice><p className="kn-reading">这次练习归入{name(profile)}的个人记录。{p?.correct?'明天试着回忆这一知识点。':'建议再听一次，并用自己的话比较不同说法。'}</p><KFacts items={[["练习次数",p?.attempts||0],["本次结果",p?.correct?'回答正确':'待再练习'],["学习版本",`v${p?.version||story.version}`],["复习建议",p?.correct?'明天回忆一次':'今天再复述一次']]}/></>,<><KButton onClick={()=>setOverlay({type:'story',id:story.id})}>再听故事</KButton><KButton primary onClick={close}>完成</KButton></>)}if(overlay.type==='course'&&personal)return wrap('规划个人学习课程',<CourseForm k={k} profile={profile} profiles={profiles} run={run} onSaved={target=>{if(target!==profile)run('profile.select',{id:target});close();if(route==='learning')setTab('courses');else go('learning','courses')}}/>);if(overlay.type==='courseRemove'){const c=courses.find(x=>x.id===overlay.id);return c?wrap('移除个人课程',<p className="kn-reading">移除“{c.title}”的规划。故事原件、收藏与学习记录继续保留。</p>,<KButton primary onClick={async()=>{if(await run('knowledge.course.remove',{id:c.id,profile}))close()}}>确认移除</KButton>):null}if(overlay.type==='gap'&&gap&&manager)return wrap('确认知识补充建议',<GapForm gap={gap} run={run} onSaved={next=>{close();if(next==='search')go('sources','query')}}/>);if(overlay.type==='sourceFailure'&&source&&manager&&!live)return wrap('模拟知识源中断',<><h3>{source.name}</h3><KNotice warn>记录同步异常：保留有效授权的本地快照，实时查询部分暂不可用。</KNotice><p className="kn-reading">中断与撤权不同。撤权须关闭有效授权；恢复同步可点击“模拟同步”。</p></>,<KButton primary onClick={async()=>{if(await run('knowledge.source.failure',{id:source.id}))close()}}>确认模拟中断</KButton>);if(overlay.type==='material'&&material&&manager&&owned(material))return wrap(overlay.target==='book'?'转为原文校核草稿':'登记来源候选',<><h3>{material.title}</h3><p className="kn-reading kn-transcription">{material.text||material.note||'尚未提交原始资料'}</p><KFacts items={[["提交者",name(material.owner)],["终端",material.terminal],["范围",scopeNames[material.scope]],["提交时间",material.at||material.created]]}/><KNotice>{overlay.target==='book'?'保留原始文字和提交信息，进入逐页人工校核，不直接发布。':'登记为停用、未授权的来源候选，确认范围与授权后才能召回。'}</KNotice></>,<KButton primary onClick={async()=>{if(await run('knowledge.material.convert',{id:material.id,target:overlay.target})){setBookId('');go(overlay.target==='book'?'collation':'sources',overlay.target==='book'?'pages':'registry')}}}>确认转换</KButton>);return null}
  return <section className="kn-workspace"><header className="kn-page-head"><div><span className="eyebrow">{live?'KNOWLEDGE / LIVE':'KNOWLEDGE / SIMULATION'}</span><h1>{title}</h1><p>{subtitle}</p></div><div className="kn-head-actions">{live&&manager&&<KButton onClick={()=>setMaterialManager({})}>原件管理</KButton>}{route==='learning'||route==='temple'?<><label className="kn-profile-label"><span>{live?'管理学习档案':'模拟学习身份'}</span><select aria-label="知识学习身份" value={profile} onChange={e=>run('profile.select',{id:e.target.value})}>{profiles.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><KButton primary disabled={!personal} onClick={()=>setOverlay({type:'course'})}>规划课程</KButton></>:manager?<KButton primary onClick={()=>setOverlay({type:route==='sources'?'source':'upload'})}>{route==='sources'?'登记知识源':'上传扫描件'}</KButton>:null}</div></header>{live&&manager&&['temple','sources'].includes(route)&&<EvidenceAssistantPanel domain="knowledge"/>}{!personal&&<KNotice>公共空间只阅读共享内容。切换具体家人，保存个人课程、收藏与学习记录。</KNotice>}{error&&!overlay&&<p className="form-error" role="alert">{error}</p>}{route==='sources'?sourcesView():route==='collation'?collationView():route==='learning'?learningView():<><Metrics items={[{label:'正式原文',value:published.length},{label:'可学故事',value:readyStories.length},{label:'我的课程',value:courses.length},{label:manager?'关键待审':'我的收藏',value:manager?totalDoubts:favorites.length}]}/><div className="kn-temple-toolbar"><KTabs current={tab} onChange={setTab} items={[{id:'stories',label:'独立故事'},{id:'graph',label:'知识脉络'},{id:'books',label:'原文基库'},{id:'courses',label:'个人课程'},...(manager?[{id:'gaps',label:'补充建议'}]:[])]}/>{['stories','books'].includes(tab)&&<input aria-label="搜索知识内容" placeholder="搜索书目、故事或概念" value={search} onChange={e=>setSearch(e.target.value)}/>}</div>{tab==='stories'&&<>{storyBookFilter&&<div className="kn-filter-book">关联书目：{k.books.find(book=>book.id===storyBookFilter)?.title}<KButton onClick={()=>setStoryBookFilter('')}>查看全部</KButton></div>}<div className="kn-row kn-between kn-stories-filter"><p className="kn-hint">{readyStories.length} 则正式故事 · 当前 {name(profile)}</p><div className="kn-actions"><KButton disabled={!personal} onClick={()=>setFavoritesOnly(v=>!v)}>{favoritesOnly?'显示全部':'只看收藏'}</KButton>{manager&&<><KButton onClick={()=>setOverlay({type:'upload'})}>上传扫描件</KButton>{live&&<KButton disabled={!published.length} onClick={()=>setOverlay({type:'storyDraft'})}>登记故事</KButton>}</>}</div></div><div className="kn-story-grid">{stories.map(storyCard)}</div>{!stories.length&&<KEmpty title="暂无匹配故事" detail="先发布精校原文，或调整搜索与收藏筛选。"/>}</>}{tab==='graph'&&graphView()}{tab==='books'&&booksView()}{tab==='gaps'&&manager&&gapsView()}{tab==='courses'&&<><div className="kn-course-grid">{courses.map(courseCard)}</div>{!courses.length&&<KEmpty title="还没有个人课程" detail="选几则已发布故事，规划属于你的学习路线。"/>}</>}</>}{dialogs()}{materialManager&&live&&manager&&<MaterialManager initialAssetIds={materialManager.ids} materialId={materialManager.materialId} onClose={()=>setMaterialManager(null)} navigate={navigate}/>}</section>
}

function EventList({items}:{items:{time:string;text:string}[]}){return <div className="kn-events">{items.map((event,i)=><div key={i}><i/><p>{event.text}</p><time>{event.time}</time></div>)}{!items.length&&<KEmpty title="暂无记录"/>}</div>}
type KnowledgeQueryHit=Omit<KnowledgeData['query']['results'][number],'book'>&{book?:string|null;page?:number|null;version?:string|number|null;location?:string;sha256?:string;offset?:number};
interface KnowledgeReference {sourceId:string;sourceName:string;title:string;kind:'book-page'|'stored-document'|'query-excerpt';location:string;sha256:string;bookId?:string;page?:number;version?:number|string;sourceRevision:number|string;text:string;contextStart:number;quote:string;quoteOffset:number;quoteStart:number;hasEarlierText:boolean;hasLaterText:boolean;resolvedAt:string;notice:string;externalUrl?:string;verifiedSourceText:boolean}
type ReferenceReader={hit:KnowledgeQueryHit;loading:boolean;issue:string;reference:KnowledgeReference|null};
function externalReferenceUrl(value:unknown):string|null {if(typeof value!=='string')return null;try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)&&!url.username&&!url.password?url.href:null}catch{return null}}
function verifiedReference(value:KnowledgeReference):KnowledgeReference {
  if(!value||!['book-page','stored-document','query-excerpt'].includes(value.kind)||typeof value.title!=='string'||typeof value.text!=='string'||typeof value.quote!=='string'||!value.quote||!Number.isSafeInteger(value.quoteStart)||value.quoteStart<0||value.text.slice(value.quoteStart,value.quoteStart+value.quote.length)!==value.quote||typeof value.verifiedSourceText!=='boolean')throw new Error('本次出处返回不完整，请重新检索后再打开。');
  if(value.kind==='query-excerpt'&&value.verifiedSourceText)throw new Error('检索摘录不能冒充已经核对的全文，请重新检索。');
  return value;
}
function QuerySection({k,profile,run,onSource}:{k:KnowledgeData;profile:string;run:RunAction;onSource:(id:string)=>void}) {
  const {data,real,handleApiError}=useDemo(),live=data.runtime?.mode==='live';
  const [busy,setBusy]=useState(false),[queryScope,setQueryScope]=useState('family'),[query,setQuery]=useState(k.query.text||''),[mode,setMode]=useState('all'),[reader,setReader]=useState<ReferenceReader|null>(null);
  const queryRecord=(real?.records.sources??[]).filter(record=>record.kind==='query'&&String(record.text??'')===k.query.text&&String(record.createdAt??'')===k.query.at).at(-1),queryId=String(queryRecord?.id||'');
  const actorId=String(data.runtime?.capabilities?.identity?.actorId||'');
  const bindings=JSON.stringify([(real?.records.sources??[]).filter(record=>record.kind==='source').map(record=>[record.id,record.revision,record.active,record.authorized,record.scope]).sort(),(real?.records.books??[]).filter(record=>record.kind==='book').map(record=>[record.id,record.revision,record.version,record.status]).sort()]);
  const context=useRef({profile,actorId,queryId,bindings});context.current={profile,actorId,queryId,bindings};
  const active=useRef(true),request=useRef<AbortController|null>(null),sequence=useRef(0);
  const closeReader=()=>{sequence.current++;request.current?.abort();request.current=null;setReader(null)};
  useEffect(()=>{closeReader()},[profile,actorId,queryId,bindings]);
  useEffect(()=>{active.current=true;const invalidate=()=>closeReader();window.addEventListener('jarvis:inbox-materials-invalidated',invalidate);return()=>{active.current=false;sequence.current++;request.current?.abort();window.removeEventListener('jarvis:inbox-materials-invalidated',invalidate)}},[]);
  const results=(k.query.results as KnowledgeQueryHit[]).filter(result=>sourceAllowed(k.sources.find(source=>source.id===result.source),profile)&&(!result.book||k.books.some(book=>book.id===result.book&&book.status==='published'&&bookAllowed(k,book,profile))));
  const failures=k.sources.filter(source=>sourceAllowed(source,profile)&&['同步异常','连接失败'].includes(source.health));
  async function submit(event:FormEvent){event.preventDefault();if(busy||!query.trim())return;closeReader();setBusy(true);try{await run('knowledge.query',{query:query.trim(),mode,profile,scope:queryScope})}finally{if(active.current)setBusy(false)}}
  async function openReference(hit:KnowledgeQueryHit) {
    request.current?.abort();const serial=++sequence.current,sharedSession=materialSessionGeneration(),started={...context.current},controller=new AbortController();request.current=controller;
    const current=()=>active.current&&sequence.current===serial&&sharedSession===materialSessionGeneration()&&Object.entries(started).every(([key,value])=>context.current[key as keyof typeof started]===value);
    setReader({hit,loading:true,issue:'',reference:null});
    if(!live||!queryId||!hit.location||!hit.sha256){setReader({hit,loading:false,issue:live?'这条检索还没有完整的出处记录，请重新检索后再打开。':'这是演示检索，没有读取真实原文。',reference:null});return}
    try {
      const reference=verifiedReference(await v1Request<KnowledgeReference>('/api/v1/knowledge/references/resolve',{method:'POST',body:JSON.stringify({queryId,source:hit.source,location:hit.location,sha256:hit.sha256}),signal:controller.signal}));
      if(current())setReader({hit,loading:false,issue:'',reference});
    } catch(error) {
      if(!current()||controller.signal.aborted)return;
      const issue=error instanceof V1Error&&error.status===403?'这份来源已经停用、撤销授权或不在当前可见范围内，无法打开。':error instanceof V1Error&&error.status===409?'这条出处的来源或原文版本已经变化，请重新检索后再打开。':error instanceof TypeError?'出处暂时无法读取，请恢复网络后再试。':error instanceof Error?error.message:'出处暂时无法读取，请重新检索。';
      setReader({hit,loading:false,issue,reference:null});
      if(error instanceof V1Error&&error.status===401)handleApiError(error);
    } finally {if(request.current===controller)request.current=null}
  }
  const reference=reader?.reference,externalUrl=externalReferenceUrl(reference?.externalUrl);
  return <section className="panel kn-query">
    <div className="kn-section-head"><div><h3>授权知识联合检索</h3><p className="kn-hint">检索授权原文、已同步资料与实时来源，结果保留出处与正文指纹。</p></div><KTag>{live?'授权原文检索':'离线模拟'}</KTag></div>
    <form className="kn-query-form" onSubmit={submit}><label>提问或关键词<input required aria-label="知识检索问题" value={query} onChange={event=>setQuery(event.target.value)} placeholder="例如：人物、学习、地理"/></label><label>检索方式<select value={mode} onChange={event=>setMode(event.target.value)}><option value="all">所有有效授权源</option><option value="local">本地与混合索引</option><option value="live">实时与混合来源</option></select></label>{live&&profile==='me'&&<label>资料范围<select value={queryScope} onChange={event=>setQueryScope(event.target.value)}>{Object.entries(scopeNames).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label>}<KButton primary type="submit" disabled={busy}>{busy?'正在检索':'开始检索'}</KButton></form>
    {failures.length>0&&<KNotice warn>{failures.map(source=>source.name).join('、')} 同步异常。已授权的本地快照可用，实时部分不完整。</KNotice>}
    <div className="kn-query-summary">{k.query.at?k.query.at+' · '+results.length+' 个匹配结果':'输入关键词，观察授权、停用与发布状态如何影响结果。'}</div>
    <div className="kn-query-results">{results.map((hit,index)=>{const source=k.sources.find(source=>source.id===hit.source);return <article key={index}><div><h3>{hit.title}</h3><p>{hit.text}</p><small>{source?.name} · {modeNames[source?.mode||'']} · {hit.book?'原文 v'+(hit.version??'待核对'):'外部来源'}{typeof hit.page==='number'?' · 第'+hit.page+'页':''}</small></div><div className="kn-query-actions"><KButton primary onClick={()=>void openReference(hit)}>打开命中内容</KButton>{profile==='me'&&<KButton onClick={()=>onSource(hit.source)}>来源配置</KButton>}</div></article>})}{k.query.at&&!results.length&&<KEmpty title="未找到匹配的有效知识" detail="可以调整关键词、恢复来源授权，或先发布相关原文。"/>}{!k.query.at&&<KEmpty title="检索结果将在这里出现" detail={live?'搜索选定范围的授权原文及实际目录／HTTP资料；来源须先同步或启用实时连接器。':'本流程只搜索统一模拟中心的样例资料，不访问实时网络。'}/>}</div>
    {reader&&<KDialog title="检索出处" wide onClose={closeReader} footer={<KButton onClick={closeReader}>关闭</KButton>}>
      {reader.loading?<p role="status">正在核对来源并读取原文…</p>:reader.issue?<><KNotice warn>{reader.issue}</KNotice><p className="kn-hint">旧的检索摘录不会替代当前原文。请关闭此处，重新检索后再打开。</p></>:reference&&<>
        <div className="kn-reference-heading"><KTag tone={reference.verifiedSourceText?'good':'warn'}>{reference.kind==='book-page'?'已发布原文':reference.verifiedSourceText?'已保存的来源正文':'检索时的摘录'}</KTag><h3>{reference.title}</h3><p>{reference.sourceName}</p><strong>{typeof reference.page==='number'?'第'+reference.page+'页'+(reference.version!==undefined?' · 原文版本 '+reference.version:''):'命中片段'}</strong></div>
        {reference.notice&&<KNotice warn={!reference.verifiedSourceText}>{reference.notice}</KNotice>}
        <section className="kn-reference-context" aria-label="前后文"><h4>{reference.verifiedSourceText?'前后文':'保留的检索摘录'}</h4><p className="kn-hint">高亮部分是检索时保留的摘录，不代表每个字都命中关键词。</p>{reference.hasEarlierText&&<p className="kn-reference-boundary">前文已省略</p>}<p className="kn-reading kn-transcription">{reference.text.slice(0,reference.quoteStart)}<mark aria-label="检索摘录">{reference.quote}</mark>{reference.text.slice(reference.quoteStart+reference.quote.length)}</p>{reference.hasLaterText&&<p className="kn-reference-boundary">后文已省略</p>}</section>
        {externalUrl&&<a className="kn-button button ghost kn-reference-link" tabIndex={0} href={externalUrl} target="_blank" rel="noopener noreferrer">打开外部原始链接</a>}
        <details className="kn-reference-details"><summary>出处详情</summary><KFacts items={[["来源定位",reference.location],["正文指纹",reference.sha256],["来源修订",reference.sourceRevision],["摘录起点",reference.quoteOffset],["上下文起点",reference.contextStart],["核对时间",reference.resolvedAt]]}/></details>
      </>}
    </KDialog>}
  </section>;
}
